const a={sex:{label:"เพศ",options:{unknown:"ไม่ทราบ",male:"เพศผู้",female:"เพศเมีย"}},neutered:{label:"ทำหมัน",options:{unknown:"ไม่ทราบ",yes:"ทำหมันแล้ว",no:"ยังไม่ทำหมัน"},closedHint:"สัตว์ที่บันทึกว่าเสียชีวิตแล้วเปลี่ยนสถานะทำหมันไม่ได้"},birthDate:{label:"วันเกิด",hint:"ไม่ทราบให้เว้นว่าง",estimated:"เป็นวันเกิดโดยประมาณ",estimatedHint:"เช่น ประเมินจากฟันของสัตว์ที่รับมาเลี้ยงตอนโตแล้ว",future:"วันเกิดต้องไม่อยู่ในอนาคต",about:e=>`ประมาณ ${e}`},age:{label:"อายุ",value:(e,t,o)=>{const n=[e>0?`${e} ปี`:"",t>0?`${t} เดือน`:""].filter(Boolean),l=n.length>0?n.join(" "):"ไม่ถึงหนึ่งเดือน";return o?`ประมาณ ${l}`:l}}};export{a as p};
